import { test, expect } from '@playwright/test';

test.describe('Form Field Labels Accessibility', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/form-page');
  });

  test('should display form fields with associated labels for screen reader users', async ({ page }) => {
    // Verify form container is visible
    const formContainer = page.getByRole('form');
    await expect(formContainer).toBeVisible();

    // Verify email input has an associated label
    const emailLabel = page.getByLabel('Email Address');
    await expect(emailLabel).toBeVisible();
    const emailInput = page.getByLabel('Email Address');
    await expect(emailInput).toBeVisible();

    // Verify password input has an associated label
    const passwordLabel = page.getByLabel('Password');
    await expect(passwordLabel).toBeVisible();
    const passwordInput = page.getByLabel('Password');
    await expect(passwordInput).toBeVisible();

    // Verify username input has an associated label
    const usernameLabel = page.getByLabel('Username');
    await expect(usernameLabel).toBeVisible();
    const usernameInput = page.getByLabel('Username');
    await expect(usernameInput).toBeVisible();

    // Verify submit button is accessible
    const submitButton = page.getByRole('button', { name: /submit/i });
    await expect(submitButton).toBeVisible();

    // Fill out form and submit
    await emailInput.fill('test@example.com');
    await passwordInput.fill('SecurePassword123');
    await usernameInput.fill('user123');
    await submitButton.click();

    // Verify success message appears
    const successMessage = page.getByText('Form submitted successfully');
    await expect(successMessage).toBeVisible();
  });

  test('should handle missing labels gracefully and provide fallback accessibility', async ({ page }) => {
    // Navigate to a page with a form missing labels
    await page.goto('/form-page-no-labels');

    // Verify form container is visible
    const formContainer = page.getByRole('form');
    await expect(formContainer).toBeVisible();

    // Verify email input exists but has no visible label
    const emailInput = page.getByPlaceholder('Enter email');
    await expect(emailInput).toBeVisible();

    // Verify email input has aria-label fallback
    const emailAriaLabel = page.getByRole('textbox', { name: /enter email/i });
    await expect(emailAriaLabel).toBeVisible();

    // Verify password input exists but has no visible label
    const passwordInput = page.getByPlaceholder('Enter password');
    await expect(passwordInput).toBeVisible();

    // Verify password input has aria-label fallback
    const passwordAriaLabel = page.getByRole('textbox', { name: /enter password/i });
    await expect(passwordAriaLabel).toBeVisible();

    // Verify submit button is accessible
    const submitButton = page.getByRole('button', { name: /submit/i });
    await expect(submitButton).toBeVisible();

    // Fill out form using placeholder text
    await emailInput.fill('test@example.com');
    await passwordInput.fill('SecurePassword123');
    await submitButton.click();

    // Verify success message appears
    const successMessage = page.getByText('Form submitted successfully');
    await expect(successMessage).toBeVisible();
  });
});
